  const w = words[0].length;
  const total = w * words.length;
  for (let i = 0; i + total <= s.length; i++) {
    const used = new Array(words.length).fill(false);
    let ok = true;
    for (let j = 0; j < words.length && ok; j++) {
      let found = false;
      for (let t = 0; t < words.length; t++) {
